<?php
require __DIR__.'/bootstrap.php';require_permission('roles.manage');$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=(string)($_POST['action']??'save');if($action==='save'){$id=(int)($_POST['id']??0);$name=trim((string)($_POST['role_name']??''));$desc=trim((string)($_POST['description']??''));$selected=array_values(array_unique(array_map('intval',$_POST['permissions']??[])));if($name==='')throw new RuntimeException('Role name is required.');if($id){$st=$pdo->prepare('SELECT role_key,is_system FROM admin_roles WHERE id=?');$st->execute([$id]);$role=$st->fetch();if(!$role)throw new RuntimeException('Role not found.');if($role['role_key']==='owner')throw new RuntimeException('Owner permissions are protected and always include full access.');$pdo->prepare('UPDATE admin_roles SET role_name=?,description=? WHERE id=?')->execute([$name,$desc,$id]);}else{$key=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-', $name),'-'));if(!$key)throw new RuntimeException('Invalid role name.');$pdo->prepare('INSERT INTO admin_roles(role_key,role_name,description,is_system,active) VALUES(?,?,?,0,1)')->execute([$key,$name,$desc]);$id=(int)$pdo->lastInsertId();}$pdo->prepare('DELETE FROM admin_role_permissions WHERE role_id=?')->execute([$id]);$ins=$pdo->prepare('INSERT INTO admin_role_permissions(role_id,permission_id) VALUES(?,?)');foreach($selected as $pid)$ins->execute([$id,$pid]);log_activity('role_update','Saved role permissions',['role_id'=>$id]);flash('success','Role permissions saved.');}
elseif($action==='delete'){$id=(int)($_POST['id']??0);$st=$pdo->prepare('SELECT role_key,is_system FROM admin_roles WHERE id=?');$st->execute([$id]);$role=$st->fetch();if(!$role)throw new RuntimeException('Role not found.');if((int)$role['is_system']===1)throw new RuntimeException('System roles cannot be deleted.');$st=$pdo->prepare('SELECT COUNT(*) FROM admin_users WHERE role_id=?');$st->execute([$id]);if((int)$st->fetchColumn()>0)throw new RuntimeException('Move users to another role before deleting this role.');$pdo->prepare('DELETE FROM admin_role_permissions WHERE role_id=?')->execute([$id]);$pdo->prepare('DELETE FROM admin_roles WHERE id=?')->execute([$id]);flash('success','Role deleted.');}header('Location: roles.php');exit;}catch(Throwable $e){$error=$e->getMessage();}}
$edit=null;$selected=[];if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM admin_roles WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();if($edit){$st=$pdo->prepare('SELECT permission_id FROM admin_role_permissions WHERE role_id=?');$st->execute([$edit['id']]);$selected=array_map('intval',array_column($st->fetchAll(),'permission_id'));}}$roles=$pdo->query('SELECT r.*,(SELECT COUNT(*) FROM admin_users u WHERE u.role_id=r.id) user_count FROM admin_roles r ORDER BY is_system DESC,id')->fetchAll();$perms=$pdo->query('SELECT * FROM admin_permissions ORDER BY permission_group,permission_name')->fetchAll();$groups=[];foreach($perms as $p)$groups[$p['permission_group']][]=$p;$pageTitle='Roles & Permissions';$active='roles';require __DIR__.'/_header.php';?>
<div class="page-heading"><div><p class="eyebrow">ACCESS CONTROL</p><h1>Roles & permissions</h1><p class="muted">Keep access intuitive: give each type of user only the tools needed for their work.</p></div><a class="button" href="roles.php?new=1">+ New custom role</a></div><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?>
<div class="roles-layout"><section class="role-list"><?php foreach($roles as $r):?><article class="role-card <?=$r['role_key']==='owner'?'protected':''?>"><div><strong><?=h($r['role_name'])?></strong><small><?=h($r['description']?:'Custom access role')?></small><span><?=$r['user_count']?> user(s) · <?=$r['is_system']?'System role':'Custom role'?></span></div><div class="actions"><?php if($r['role_key']!=='owner'):?><a class="button secondary small" href="?edit=<?=$r['id']?>">Permissions</a><?php else:?><span class="badge success">Full access</span><?php endif;?><?php if(!$r['is_system']):?><form method="post" data-swal-confirm="Delete this role?" data-swal-text="Only unused custom roles can be removed."><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="button danger-lite small">Delete</button></form><?php endif;?></div></article><?php endforeach;?></section>
<?php if($edit||isset($_GET['new'])):?><section class="panel role-editor"><div class="panel-heading"><div class="panel-icon"><?=icon('shield')?></div><div><h2><?=$edit?'Edit role':'Create custom role'?></h2><p>Select the exact actions this role can perform.</p></div></div><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><label>Role name<input name="role_name" required value="<?=h($edit['role_name']??'')?>"></label><label>Description<textarea name="description"><?=h($edit['description']??'')?></textarea></label><div class="permission-groups"><?php foreach($groups as $group=>$items):?><fieldset><legend><?=h($group)?></legend><?php foreach($items as $p):?><label class="permission-check"><input type="checkbox" name="permissions[]" value="<?=$p['id']?>" <?=in_array((int)$p['id'],$selected,true)?'checked':''?>><span><b><?=h($p['permission_name'])?></b><small><?=h($p['permission_key'])?></small></span></label><?php endforeach;?></fieldset><?php endforeach;?></div><div class="form-actions"><button>Save role</button><a class="button secondary" href="roles.php">Cancel</a></div></form></section><?php endif;?></div>
<?php require __DIR__.'/_footer.php';
